<script setup lang="ts">
import { marketingMoney, type MarketingReport } from "~/utils/businessMarketing";
import { reportNumber } from "~/utils/businessReport";
import { adEfficiency } from "~/utils/businessDecisions";
const props = defineProps<{ ads: NonNullable<MarketingReport["ads"]> }>();
type Campaign = NonNullable<NonNullable<MarketingReport["ads"]>["campaigns"]>[number];
const money = (value?: string | number | null) => marketingMoney(value, props.ads.currency);
const objectives: Record<string, string> = { OUTCOME_SALES: "გაყიდვები", CONVERSIONS: "კონვერსიები", PRODUCT_CATALOG_SALES: "კატალოგის გაყიდვები", OUTCOME_TRAFFIC: "ვიზიტები", LINK_CLICKS: "ბმულზე კლიკები", OUTCOME_ENGAGEMENT: "ჩართულობა", OUTCOME_LEADS: "მომართვები", LEAD_GENERATION: "მომართვები", OUTCOME_AWARENESS: "ცნობადობა", BRAND_AWARENESS: "ცნობადობა", REACH: "მიღწევა", POST_ENGAGEMENT: "პოსტის ჩართულობა", VIDEO_VIEWS: "ვიდეოს ნახვა", OUTCOME_APP_PROMOTION: "აპის პოპულარიზაცია" };
const statuses: Record<string, string> = { ACTIVE: "ჩართულია", PAUSED: "გამორთულია", ARCHIVED: "არქივშია", DELETED: "წაშლილია", WITH_ISSUES: "გადასამოწმებელია", IN_PROCESS: "მუშავდება", DISAPPROVED: "უარყოფილია", PENDING_REVIEW: "შემოწმების მოლოდინშია", CAMPAIGN_PAUSED: "კამპანია გამორთულია", ADSET_PAUSED: "ჯგუფი გამორთულია" };
const result = (campaign: Campaign) => {
  if (["OUTCOME_SALES", "CONVERSIONS", "PRODUCT_CATALOG_SALES"].includes(campaign.objective || "")) return { label: "შეძენები · Meta", value: campaign.website_purchases };
  if (campaign.objective === "OUTCOME_TRAFFIC") return { label: "გვერდის ჩატვირთვები", value: campaign.landing_page_views };
  if (campaign.objective === "LINK_CLICKS") return { label: "ბმულზე კლიკები", value: campaign.link_clicks };
  return { label: "მიზნის საზომი ამ ანგარიშში მიუწვდომელია", value: null };
};
const cost = (campaign: Campaign) => { const count = Number(result(campaign).value); return count > 0 ? money(Number(campaign.spend) / count) : "—"; };
</script>
<template>
  <section class="my-6 overflow-hidden rounded-xl border border-border-default bg-surface" aria-labelledby="campaigns-title">
    <div class="p-5"><h2 id="campaigns-title" class="text-lg font-bold">კამპანიები · ხარჯი და შედეგი</h2><p class="mt-2 text-xs leading-6 text-text-muted">წყარო: Meta · {{ ads.currency }} · დღეები: {{ ads.timezone }}. სტატუსი მიმდინარეა; შედეგები არჩეულ პერიოდს ეხება. მიზანი კამპანიის დონეზეა; ჯგუფის ოპტიმიზაცია Ads Manager-ში ჩანს.</p><p v-if="ads.campaign_metadata_status !== 'ready'" class="mt-2 text-xs text-text-muted">ზოგი კამპანიის მიზანი ან სტატუსი ვერ მივიღეთ; ხარჯი და მიღებული შედეგები შენარჩუნებულია.</p><p v-if="ads.campaigns_limited" class="mt-2 text-xs text-text-muted">ნაჩვენებია პირველი 300 კამპანია; ანგარიშის ჯამები მათ შეკრებაზე არ არის დამოკიდებული.</p></div>
    <div v-if="ads.campaigns?.length" class="overflow-auto"><table class="w-full text-left text-xs"><thead class="bg-surface-2"><tr><th class="p-3">კამპანია / მიზანი / სტატუსი</th><th class="p-3 text-right">ხარჯი</th><th class="p-3 text-right">ბმულზე კლიკები</th><th class="p-3 text-right">გვერდის ჩატვირთვები</th><th class="p-3 text-right">შედეგის საზომი</th><th class="p-3 text-right">ერთი შედეგის ფასი</th><th class="p-3">დეტალები</th></tr></thead><tbody><tr v-for="campaign in ads.campaigns" :key="campaign.id" class="border-t border-border-default align-top"><td class="min-w-[190px] max-w-[300px] break-words p-3"><strong>{{ campaign.name }}</strong><p class="mt-2">{{ objectives[campaign.objective || ''] || 'მიზანი უცნობია' }}</p><p class="mt-1 text-text-muted">{{ statuses[campaign.effective_status || ''] || 'სტატუსი უცნობია' }}</p></td><td class="whitespace-nowrap p-3 text-right">{{ money(campaign.spend) }}</td><td class="p-3 text-right">{{ reportNumber(campaign.link_clicks) }}</td><td class="p-3 text-right">{{ reportNumber(campaign.landing_page_views) }}</td><td class="min-w-[150px] p-3 text-right"><strong>{{ reportNumber(result(campaign).value) }}</strong><p class="mt-1 text-text-muted">{{ result(campaign).label }}</p></td><td class="whitespace-nowrap p-3 text-right">{{ cost(campaign) }}</td><td class="min-w-[220px] p-3"><details><summary class="min-h-[44px] cursor-pointer font-semibold">მაჩვენებლების ნახვა</summary><dl class="space-y-2 leading-6"><div><dt>ჩვენებები</dt><dd>{{ reportNumber(campaign.impressions) }}</dd></div><div><dt>მიღწეული ანგარიშები</dt><dd>{{ reportNumber(campaign.reach) }}</dd></div><div><dt>ყველა კლიკი · არა მხოლოდ საიტზე გადასვლა</dt><dd>{{ reportNumber(campaign.clicks) }}</dd></div><div><dt>Meta-სთვის მიწერილი შეძენები</dt><dd>{{ reportNumber(campaign.website_purchases) }}</dd></div><div><dt>Meta-სთვის მიწერილი თანხა</dt><dd>{{ money(campaign.website_purchase_value) }}</dd></div><div><dt>ერთი შეძენის ფასი</dt><dd>{{ money(adEfficiency(campaign).cpa) }}</dd></div><div><dt>ROAS · შემოსავლის შეფარდება ხარჯთან</dt><dd>{{ adEfficiency(campaign).roas === null ? '—' : `${reportNumber(Math.round(adEfficiency(campaign).roas! * 100) / 100)}×` }}</dd></div></dl></details></td></tr></tbody></table></div><p v-else class="p-5 text-sm text-text-muted">არჩეულ პერიოდში კამპანიების აქტივობა არ არის.</p>
    <p class="border-t border-border-default p-5 text-xs leading-6 text-text-muted">შეძენა რეკლამას მიეწერება დაწკაპუნებიდან 7 დღეში ან ნახვიდან 1 დღეში, შეძენის თარიღით. ეს ანგარიშის საერთო წესია და Ads Manager-ის სხვა არჩეული წესის შედეგს შეიძლება განსხვავდებოდეს. ROAS მოგება არ არის. USD ხარჯს GA4-ის GEL თანხაზე არ ვყოფთ; Meta-ს შეძენებს ჩვენი ბაზისა და Google-ის შეძენებს არ ვუმატებთ. მცირე რაოდენობით კამპანიის საბოლოო ეფექტიანობა არ დასტურდება.</p>
  </section>
</template>
